<?php
/** Proof — custom fields (spec "Proof", 6): the definitions, the validator (drops a field for other types, refuses a bad date and an unknown option, booleans a checkbox), what a ticket lacks on solve. */
require __DIR__ . '/lib.php';
require dirname(__DIR__, 3) . '/app/features/fields/validate.php';
$owner = as_member(1);
$req = requester_of_member(26);
$incident = type_id('incident'); $problem = type_id('problem');

echo "1. Definitions\n";
$since = last_activity_id();
[$c, $b] = act($owner, '/settings/fields/save.php', ['label' => 'SMOKE Asset tag', 'applies_to' => 'ticket', 'field_type' => 'text', 'required_on_solve' => 'yes']);
$asset = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $asset > 0 && (string) one('SELECT key FROM custom_field_defs WHERE id = :f', ['f' => $asset]) === 'smoke_asset_tag' && count(activity('field.save', $since)) === 1, 'field_save: key derived, logged');
[$c, $b] = act($owner, '/settings/fields/save.php', ['label' => 'SMOKE Asset tag 2', 'key' => 'smoke_asset_tag', 'applies_to' => 'ticket', 'field_type' => 'text']);
ok($c === 422 && msg($b) === 'A field with that key already exists for tickets.', 'a key clash: 422 "A field with that key already exists for tickets."');
[$c, $b] = act($owner, '/settings/fields/save.php', ['label' => 'SMOKE Asset tag', 'key' => 'smoke_asset_tag', 'applies_to' => 'organization', 'field_type' => 'text']);
ok($c === 200, 'the same key for organizations: fine');
$orgField = (int) $b['record_id'];
[$c, $b] = act($owner, '/settings/fields/save.php', ['label' => 'SMOKE Root cause', 'applies_to' => 'ticket', 'field_type' => 'select', 'options' => "Hardware\nSoftware\nNetwork", 'types' => [$problem]]);
$cause = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $cause > 0 && q('SELECT options, type_ids FROM custom_field_defs WHERE id = :f', ['f' => $cause])[0] == ['options' => '{Hardware,Software,Network}', 'type_ids' => '{' . $problem . '}'], 'a select for problems only: options and type_ids stored');
[$c, $b] = act($owner, '/settings/fields/save.php', ['label' => 'SMOKE Empty select', 'applies_to' => 'ticket', 'field_type' => 'select']);
ok($c === 422 && isset(fields($b)['options']), 'a select without options: 422');
[$c, $b] = act($owner, '/settings/fields/save.php', ['label' => 'SMOKE Due', 'applies_to' => 'ticket', 'field_type' => 'date']);
$due = (int) $b['record_id'];
[$c, $b] = act($owner, '/settings/fields/save.php', ['label' => 'SMOKE Approved', 'applies_to' => 'ticket', 'field_type' => 'checkbox']);
$appr = (int) $b['record_id'];
[$c, $b] = act($owner, '/settings/fields/save.php', ['label' => 'SMOKE Seats', 'applies_to' => 'organization', 'field_type' => 'number', 'requester_visible' => 'yes']);
$seats = (int) $b['record_id'];
[$c, $b] = act($owner, '/settings/fields/save.php', ['label' => 'SMOKE Areas', 'applies_to' => 'ticket', 'field_type' => 'multi_select', 'options' => ['North', 'South']]);
$areas = (int) $b['record_id'];
[$c, $b] = act($owner, '/settings/fields/save.php', ['field' => $asset, 'applies_to' => 'requester', 'label' => 'SMOKE Asset tag!']);
ok($c === 200 && q('SELECT applies_to, label FROM custom_field_defs WHERE id = :f', ['f' => $asset])[0] === ['applies_to' => 'ticket', 'label' => 'SMOKE Asset tag!'], 'applies_to is immutable (a changed value ignored); the label changes');
act($owner, '/settings/fields/save.php', ['field' => $asset, 'label' => 'SMOKE Asset tag']);
[$c, $d] = screen($owner, '/settings/fields/');
ok(count(array_filter($d['fields'], fn ($f) => $f['applies_to'] === 'ticket')) >= 5 && count(array_filter($d['fields'], fn ($f) => $f['applies_to'] === 'organization')) === 2, 'the list groups them: ticket fields and two for organizations');
$body = page($owner, '/settings/fields/')['body'];
ok(str_contains($body, 'id="fields-group-ticket"') && str_contains($body, 'id="field-row-' . $cause . '-types">for Problem') && str_contains($body, 'id="fields-group-requester-empty"'), 'the screen: the groups, "for Problem", the empty requester group');

echo "2. The validator\n";
$pdo = pdo();
$shown = array_column(fields_for($pdo, 'ticket', $incident), 'key');
ok(in_array('smoke_asset_tag', $shown, true) && !in_array('smoke_root_cause', $shown, true), 'fields_for(ticket, incident) shows the asset tag, not the problems-only cause');
ok(in_array('smoke_root_cause', array_column(fields_for($pdo, 'ticket', $problem), 'key'), true), 'fields_for(ticket, problem) shows the cause');
$r = custom_values_validate($pdo, 'ticket', ['smoke_asset_tag' => ' A-17 ', 'smoke_root_cause' => 'Hardware', 'smoke_due' => '2026-13-40', 'smoke_approved' => 'yes', 'smoke_areas' => 'North,West', 'nonsense' => 'x'], $incident);
ok($r['values'] === ['smoke_asset_tag' => 'A-17', 'smoke_approved' => true] || ($r['values']['smoke_asset_tag'] ?? '') === 'A-17', 'an incident: the asset tag cleaned, the problems-only cause dropped silently, the checkbox a boolean');
ok(isset($r['errors']['smoke_due']) && str_contains($r['errors']['smoke_due'], 'date') && isset($r['errors']['smoke_areas']) && isset($r['errors']['nonsense']) && !isset($r['errors']['smoke_root_cause']), 'a bad date, an unknown multi-select option and an unknown key are errors; the dropped field is not');
$r = custom_values_validate($pdo, 'ticket', ['smoke_root_cause' => 'Magic'], $problem);
ok($r['errors']['smoke_root_cause'] === 'SMOKE Root cause is one of: Hardware, Software, Network.', 'a problem with an unknown option: refused in words');
$r = custom_values_validate($pdo, 'ticket', ['smoke_root_cause' => 'Software', 'smoke_areas' => ['South'], 'smoke_due' => '2026-12-31', 'smoke_approved' => 'no'], $problem);
ok($r['errors'] === [] && $r['values'] == ['smoke_root_cause' => 'Software', 'smoke_areas' => ['South'], 'smoke_due' => '2026-12-31', 'smoke_approved' => false], 'a good set cleans whole');
$r = custom_values_validate($pdo, 'organization', ['smoke_seats' => '12', 'smoke_asset_tag' => 'x']);
ok($r['errors'] === [] && $r['values'] === ['smoke_seats' => 12, 'smoke_asset_tag' => 'x'], 'organization values: a number is numeric, the org\'s own asset tag text');
$r = custom_values_validate($pdo, 'organization', ['smoke_seats' => 'twelve']);
ok(isset($r['errors']['smoke_seats']), 'a non-number: error');
act($owner, '/settings/fields/archive.php', ['field' => $areas]);
$r = custom_values_validate($pdo, 'ticket', ['smoke_areas' => 'North'], $incident);
ok($r['errors'] === [] && $r['values'] === [], 'an archived field is dropped, not an error');

echo "3. Missing on solve\n";
$t = mkticket($req, general_queue(), 'SMOKE needs a tag');
q('UPDATE tickets SET type_id = :y, custom_values = :v WHERE id = :t', ['y' => $incident, 'v' => '{}', 't' => $t]);
ok(custom_values_missing_on_solve($pdo, $t) === ['smoke_asset_tag' => 'SMOKE Asset tag'], 'a ticket with no asset tag lacks it on solve');
q('UPDATE tickets SET custom_values = :v WHERE id = :t', ['v' => '{"smoke_asset_tag": "A-1"}', 't' => $t]);
ok(custom_values_missing_on_solve($pdo, $t) === [], 'with the tag set: nothing missing');
act($owner, '/settings/fields/save.php', ['field' => $cause, 'required_on_solve' => 'yes']);
ok(custom_values_missing_on_solve($pdo, $t) === [], 'the cause, required but for problems only, is not missing on an incident');
q('UPDATE tickets SET type_id = :y WHERE id = :t', ['y' => $problem, 't' => $t]);
ok(custom_values_missing_on_solve($pdo, $t) === ['smoke_root_cause' => 'SMOKE Root cause'], 'as a problem it is');
$since = last_activity_id();
[$c, $b] = act($owner, '/settings/fields/archive.php', ['field' => $due]);
ok($c === 200 && one('SELECT archived_at FROM custom_field_defs WHERE id = :f', ['f' => $due]) !== null && count(activity('field.archive', $since)) === 1, 'field_archive: archived and logged');
$body = page($owner, '/settings/fields/' . $cause . '/edit')['body'];
ok(str_contains($body, 'id="field-form-field-type-' . $problem . '" checked') && str_contains($body, 'readonly') && str_contains($body, 'Hardware'), 'the edit form shows the type checked, the key read-only and the options');
finish();
